// MarshalJSON implements json.Marshaler. Exactly one variant
// pointer must be non-nil; otherwise marshaling errors.
func (j Node) MarshalJSON() ([]byte, error) {
	set := 0
	if j.Leaf != nil {
		set++
	}
	if j.Some != nil {
		set++
	}
	if j.Every != nil {
		set++
	}
	if set != 1 {
		return nil, fmt.Errorf("Node: exactly one variant must be set, got %d", set)
	}
	if j.Leaf != nil {
		return json.Marshal(j.Leaf)
	}
	if j.Some != nil {
		return json.Marshal(j.Some)
	}
	if j.Every != nil {
		return json.Marshal(j.Every)
	}
	return nil, nil // unreachable
}

// MarshalYAML mirrors MarshalJSON.
func (j Node) MarshalYAML() (interface{}, error) {
	set := 0
	if j.Leaf != nil {
		set++
	}
	if j.Some != nil {
		set++
	}
	if j.Every != nil {
		set++
	}
	if set != 1 {
		return nil, fmt.Errorf("Node: exactly one variant must be set, got %d", set)
	}
	if j.Leaf != nil {
		return j.Leaf, nil
	}
	if j.Some != nil {
		return j.Some, nil
	}
	if j.Every != nil {
		return j.Every, nil
	}
	return nil, nil // unreachable
}

// UnmarshalJSON implements json.Unmarshaler. It peeks the
// discriminator property "kind" and dispatches the decode into the
// matching variant.
func (j *Node) UnmarshalJSON(value []byte) error {
	// Reset to zero value so reusing the same holder across multiple
	// Unmarshal calls doesn't leave a previous winner set alongside the
	// new one (which would violate the one-variant-set invariant and
	// break the corresponding MarshalJSON).
	*j = Node{}
	var peek struct {
		Discriminator json.RawMessage `json:"kind"`
	}
	if err := json.Unmarshal(value, &peek); err != nil {
		return fmt.Errorf("unmarshal Node: %w", err)
	}
	if len(peek.Discriminator) == 0 {
		return fmt.Errorf("Node: missing discriminator field kind")
	}
	if string(peek.Discriminator) == "null" {
		return fmt.Errorf("Node: kind discriminator must be a string, got null")
	}
	var disc string
	if err := json.Unmarshal(peek.Discriminator, &disc); err != nil {
		return fmt.Errorf("Node: kind discriminator must be a string: %w", err)
	}
	switch disc {
	case "leaf":
		var v NodeLeaf
		if err := json.Unmarshal(value, &v); err != nil {
			return fmt.Errorf("Node.Leaf: %w", err)
		}
		j.Leaf = &v
	case "some":
		var v NodeSome
		if err := json.Unmarshal(value, &v); err != nil {
			return fmt.Errorf("Node.Some: %w", err)
		}
		j.Some = &v
	case "every":
		var v NodeEvery
		if err := json.Unmarshal(value, &v); err != nil {
			return fmt.Errorf("Node.Every: %w", err)
		}
		j.Every = &v
	default:
		return fmt.Errorf("Node: unknown kind value %q", disc)
	}
	return nil
}

// UnmarshalYAML mirrors UnmarshalJSON: peek the discriminator
